<section class="page-intro"><div><p>Neměnný záznam přihlášení, změn a výsledků synchronizačních úloh.</p></div><div class="search-box large"><?= icon('search') ?><input type="search" placeholder="Hledat v historii" data-table-search="audit-table"></div></section>
<section class="panel"><div class="table-wrap"><table class="data-table" id="audit-table"><thead><tr><th>Čas</th><th>Uživatel</th><th>Událost</th><th>Objekt</th><th>Výsledek RouterOS / podrobnosti</th><th>IP administrace</th></tr></thead><tbody><?php if ($entries === []): ?><tr class="empty-row"><td colspan="6"><strong>Historie je zatím prázdná</strong></td></tr><?php endif; ?><?php foreach ($entries as $entry): $details = json_decode((string) ($entry['details_json'] ?? ''), true); ?><tr data-search-row><td><?= e(format_datetime($entry['created_at'])) ?></td><td><strong><?= e($entry['user_name'] ?: 'Systém') ?></strong></td><td><span class="audit-action"><?= icon(str_contains($entry['action'],'failed')?'alert':'history') ?><span><strong><?= e($entry['summary']) ?></strong><small><?= e($entry['action']) ?></small></span></span></td><td><?= e(($entry['entity_type'] ?: '—') . ($entry['entity_id'] ? ' #'.$entry['entity_id'] : '')) ?></td><td><?php if (is_array($details) && $details !== []): ?><details class="audit-details"><summary>Zobrazit</summary><pre><?= e(json_encode($details, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)) ?></pre></details><?php else: ?>—<?php endif; ?></td><td class="mono"><?= e($entry['ip_address'] ?: '—') ?></td></tr><?php endforeach; ?></tbody></table></div></section>
